const r = $('Buscar memoria').first().json || {};
const f = r.fields || r;
const nuevo = !r.id;
const nombre = f.Nombre_Usuario || '';
const estado = f['Estado del Caso'] || 'Nuevo';
const resumen = f['Resumen Consolidado'] || '';
const contador = Number(f.Contador_Mensajes || 0);
const contexto = nuevo
  ? 'Usuario nuevo: sin historial previo.'
  : `Nombre: ${nombre || 'no informado'}\nEstado del caso: ${estado}\nResumen de la ultima charla: ${resumen || 'sin resumen'}`;
return [{ json: { usuario_nuevo: nuevo, contexto_memoria: contexto, contador } }];

const filas = $input.all().map(i => i.json).filter(r => r['Mensaje Original']);
const cortar = (t) => String(t ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300);
const historial = filas.slice(-6)
  .map(r => `Cliente: ${cortar(r['Mensaje Original'])}\nAsistente: ${cortar(r['Respuesta'])}`)
  .join('\n---\n');
return [{ json: { historial } }];

